    },
    {
      "card_ids": ["C05"],
      "claim": "A morpholine-containing CNS agent was rapidly distributed to mouse brain with brain concentrations exceeding plasma concentrations, supporting the CNS-permeable potential of morpholine-bearing small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tecovirimat, a CF3-aryl small molecule, crosses the blood-brain barrier in animal studies, providing additional support for CF3-aryl CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A CF3-heteroaryl molecule was shown by PET to cross the BBB, albeit with relatively low uptake, confirming that this structural class is not intrinsically excluded from the CNS.",
